questionvariables.text:
func_coeff: rand(8)+3;
func_power: rand(5)+2;

func: func_coeff*x^func_power;
lim_point: rand(4)+2;

corr_ans: [1, true, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow 0} \\frac{", func_coeff, (lim_point + h)^func_power, "-", func_coeff*lim_point^func_power, "}{h} \\)")];

/* wrong answers */
/* 2: leaves x in the second term of the numerator */
/* 3: leaves x in the first term of the numerator */
/* 4: leaves x both terms in the numerator */
/* 5: brings power inside brackets for first term in numerator */
/* 6: takes h to the wrong limit */

incorr_ans: rand_selection([

[2, false, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow 0} \\frac{", func_coeff, (lim_point + h)^func_power, "-", func_coeff, x^func_power, "}{h} \\)")],

[3, false, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow 0} \\frac{", func_coeff, (x + h)^func_power, "-", func_coeff*lim_point^func_power, "}{h} \\)")],

[4, false, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow 0} \\frac{", func_coeff, (x + h)^func_power, "-", func_coeff, x^func_power, "}{h} \\)")],

[5, false, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow 0} \\frac{", func_coeff, "(", lim_point + h^func_power, ")", "-", func_coeff*lim_point^func_power, "}{h} \\)")],

[6, false, sconcat("\\(\\displaystyle \\lim_{h \\rightarrow", lim_point, "} \\frac{", func_coeff, (lim_point + h)^func_power, "-", func_coeff*lim_point^func_power, "}{h} \\)")]

], 3);

ma: random_permutation(append([corr_ans], incorr_ans));

/*worked solution */
num_left: expand((lim_point + h)^func_power); 
num_left1: expand(func_coeff*num_left); 
num_right:func_coeff*(lim_point)^func_power;
func_num:num_left1-num_right;
func_num_simp:factor(func_num);
func_num_simp1:expand(func_num_simp/h); 
/* Calculate the limit as h approaches 0 */
coef:coeff(func_num_simp1,h,0);
coef:coeff(func_num_simp1,h,1); 
correct_limit:limit(func_num_simp1, h, 0);
